"""Original lessons guided by Doyen's Grade 7 Mathematics Term II 2025 scheme.

The scheme supplies sequence and curriculum guidance, not these worked examples.
Week 8 is a break; week 14 is assessment. New courses remain drafts for review.
"""

SOURCE = "Doyen Publishers, Grade 7 Mathematics, Term II 2025 scheme of work"
from educations.course_visuals import visual_for_slot


def lesson(week, number, pages, book, title, outcomes, content, activity, questions, answers, inquiry, resources="Exercise book, pencil, ruler"):
    return {
        **visual_for_slot(week, number),
        "title": title,
        "description": f"Week {week}, lesson {number}: {inquiry}",
        "curriculum_reference": f"Grade 7 Mathematics | Term II 2025 | Week {week}, lesson {number} | Scheme pp. {pages} | Smart Minds Grade 7 pp. {book}",
        "learning_outcomes": outcomes,
        "lesson_content": content,
        "activities": f"Inquiry: {inquiry}\n\nResources: {resources}. Optional book reference: Smart Minds Mathematics Grade 7, pp. {book} (as listed in the supplied scheme).\n\n{activity}\n\nReflection: Explain one method you used and one mistake you learned to avoid.",
        "assessment": f"{questions}\n\nSuccess criteria: Show your method, use correct notation and units where needed, and explain why your answer makes sense. Assessment can use written work, oral explanation and observation of the activity.",
        "teacher_notes": f"Suggested answers / marking guidance:\n{answers}\n\nSource mapping: {SOURCE}, pp. {pages}; week {week}, lesson {number}. Outcomes are paraphrased; explanations, examples and questions are newly authored. Review against your school curriculum before publishing.",
    }


def course(key, title, summary, duration, strand, modules):
    return {
        "slug": f"grade-7-term-2-{key}", "title": title, "summary": summary,
        "duration_weeks": duration,
        "description": f"Grade 7 Mathematics - {strand}.\n\n{summary}\n\nTeaching sequence guided by {SOURCE}. Module references identify the scheme pages, weeks, lessons and suggested textbook pages. Week 8 is the midterm break. Review the editable teaching content before publication.",
        "modules": modules,
    }


